  "Baseline: Post Office City Costs Barometer, 22 May 2026. Two nights in a central three-star double room, one dinner for two and a 48-hour transit pass per person. Hotel sample: 5–7 June. Survey prices are not current selling prices; current FX does not update them.": "Referință: Barometrul Costurilor Orașelor Post Office, 22 mai 2026. Două nopți într-o cameră dublă centrală de trei stele, o cină pentru două persoane și un abonament de tranzit de 48 de ore per persoană. Exemplu hotel: 5–7 iunie. Prețurile sondajului nu sunt prețuri curente de vânzare; cursul valutar curent nu le actualizează.",
  "Baselines are Budget Your Trip traveller spending averages, not countrywide or current hotel prices. Their collection month is unknown, so CPI is not added. The dated-quote calculator below applies inflation where a compatible monthly index exists.": "Referințele sunt medii de cheltuieli ale călătorilor Budget Your Trip, nu prețuri la nivel de țară sau prețuri curente ale hotelurilor. Luna colectării lor este necunoscută, deci IPC nu este adăugat. Calculatorul de cotații datat de mai jos aplică inflația acolo unde există un indice lunar compatibil.",
