  "Dated discovery data for 199 passports, not current official entry clearance. ETA and entry restrictions use the unknown colour and are explained in details. Three Turkish ID-card entries from the MFA are separately included; see conditions in details.": "Date orientative, datate, pentru 199 de pașapoarte, nu o confirmare oficială actuală a dreptului de intrare. ETA și restricțiile de intrare folosesc culoarea pentru statut necunoscut și sunt explicate în detalii. Sunt incluse separat trei destinații accesibile cu cartea de identitate turcească, conform Ministerului Afacerilor Externe; vezi condițiile în detalii.",
  "Day 2: Allow time for Galata and Beyoğlu, adapting walks and breaks to your pace.": "Ziua 2: Rezervă timp pentru Galata și Beyoğlu, adaptând plimbările și pauzele la ritmul tău.",
