  "TRY conversion is omitted for rates older than 7 days. Season, tax and exchange margins affect actual costs. The old Baku example is excluded from current-price rankings.": "Conversia în TRY este omisă pentru cursurile mai vechi de 7 zile. Sezonul, taxele și marjele de schimb afectează costurile reale. Vechiul exemplu pentru Baku este exclus din clasamentele prețurilor actuale.",
  "TRY rate unavailable": "Cursul TRY nu este disponibil",
  "Tap Add favourite. We will continue once it has been saved successfully.": "Apasă Adaugă la favorite. Vom continua după salvarea cu succes.",
  "Tap My countries in Plans. This is your wishlist of saved countries, separate from the countries you have visited.": "Apasă Țările mele din Planuri. Aceasta este lista țărilor în care vrei să mergi, separată de țările vizitate.",
  "Tap Open plan on a route. Lesson plans are labelled “Learning example” in their names.": "Apasă Deschide planul pe o rută. Planurile lecțiilor au „Exemplu de învățare” în nume.",
  "Tap Save on an event you like. Once saved, reopen it here or in Plans.": "Apasă Salvează pe un eveniment care îți place. După salvare, redeschide-l aici sau din Planuri.",
  "Tap a heart in Explore to keep your favourite countries here.": "Apasă o inimă în Explorează pentru a-ți păstra țările favorite aici.",
  "Tap the country you saved. You have now learned how to discover, save and find a place again.": "Apasă țara pe care ai salvat-o. Acum ai învățat cum să descoperi, să salvezi și să regăsești un loc.",
  "Tap your route start on the map.": "Atinge pe hartă punctul de început al rutei tale.",
