  "Text size": "Dimensiunea textului",
  "Text to translate": "Text de tradus",
  "The AI planning service cannot accept another request right now. Your preferences are kept; please retry later.": "Serviciul AI de planificare nu poate accepta încă o cerere momentan. Preferințele tale sunt păstrate; încearcă mai târziu.",
  "The AI planning service cannot create new plans because its daily capacity limit has been reached. Your preferences and previous plan are kept.": "Serviciul AI de planificare nu poate crea planuri noi deoarece a fost atinsă limita zilnică de capacitate. Preferințele și planul tău anterior sunt păstrate.",
  "The AI planning service is currently unavailable. Your preferences are kept; please retry later.": "Serviciul AI de planificare nu este disponibil momentan. Preferințele tale sunt păstrate; încearcă mai târziu.",
  "The May reference rate could not be verified, so no local-price or CPI calculation is shown. The original GBP amount is preserved above.": "Cursul de referință din mai nu a putut fi verificat, așa că nu este afișat niciun calcul de preț local sau IPC. Suma originală în GBP este păstrată mai sus.",
  "The action could not be completed.": "Acțiunea nu a putut fi finalizată.",
  "The alert could not be saved. Check the details and try again.": "Alerta nu a putut fi salvată. Verifică detaliile și încearcă din nou.",
  "The checklist could not be saved.": "Lista de pregătiri nu a putut fi salvată.",
  "The code could not be copied; press and hold to copy.": "Codul nu a putut fi copiat; ține apăsat pentru a-l copia.",
  "The community feed could not be loaded. Check your connection and try again.": "Fluxul comunității nu s-a încărcat. Verifică conexiunea și încearcă din nou.",
  "The connection failed or the search timed out. Retry or continue manually.": "Conexiunea a eșuat sau căutarea a expirat. Reîncearcă sau continuă manual.",
  "The deletion is saved on this device and will retry when connected.": "Ștergerea este salvată pe acest dispozitiv și va fi reîncercată la conectare.",
  "The draft may include the screen name and app version. Do not include passwords, booking references or identity documents.": "Schița poate include numele ecranului și versiunea aplicației. Nu include parole, coduri de rezervare sau documente de identitate.",
  "The event could not be added to the trip.": "Evenimentul nu a putut fi adăugat în călătorie.",
  "The event list could not load. Previously loaded records are kept.": "Lista evenimentelor nu s-a încărcat. Înregistrările încărcate anterior sunt păstrate.",
  "The event source cannot be checked right now. Showing the last verified details.": "Sursa evenimentului nu poate fi verificată momentan. Sunt afișate ultimele detalii verificate.",
  "The event will be removed from this device and its reminder cancelled. An item already added to a trip checklist stays there.": "Evenimentul va fi eliminat de pe acest dispozitiv, iar mementoul va fi anulat. Un element deja adăugat în lista de pregătiri a unei călătorii rămâne acolo.",
  "The evidence could not be opened in the device viewer.": "Dovada nu a putut fi deschisă în vizualizatorul dispozitivului.",
  "The example could not be saved. Free some device storage and retry. Your existing plans are kept.": "Exemplul nu a putut fi salvat. Eliberează spațiu pe dispozitiv și încearcă din nou. Planurile existente sunt păstrate.",
  "The fixed time conflicts with the previous stop.": "Ora fixată se suprapune cu oprirea anterioară.",
  "The flight number differs from the PNR. Use the departure airport's local date.": "Numărul zborului este diferit de PNR. Folosește data locală a aeroportului de plecare.",
  "The iPhone view could not open; your progress is saved here.": "Afișarea pe iPhone nu a putut fi deschisă; progresul tău este salvat aici.",
  "The image could not be processed. Choose another image or remove it and try again.": "Imaginea nu a putut fi procesată. Alege altă imagine sau elimin-o și încearcă din nou.",
  "The invitation could not be accepted.": "Invitația nu a putut fi acceptată.",
  "The item could not be deleted.": "Elementul nu a putut fi șters.",
  "The last 7 days from GDELT, Anadolu Agency and BBC. Publication dates are shown when supplied; a news date is not the event date. Headlines retain their original language.": "Ultimele 7 zile de la GDELT, Anadolu Agency și BBC. Datele publicării sunt afișate când sunt furnizate; data unei știri nu este data evenimentului. Titlurile își păstrează limba originală.",
  "The last map result has expired. Load places again.": "Ultimul rezultat al hărții a expirat. Încarcă locurile din nou.",
  "The last retrieved map of this area was saved to your device. Check its data date below.": "Ultima hartă preluată pentru această zonă a fost salvată pe dispozitiv. Verifică mai jos data informațiilor.",
  "The map could not be removed. Try again.": "Harta nu a putut fi eliminată. Încearcă din nou.",
  "The new password must be 8–128 characters.": "Parola nouă trebuie să aibă 8–128 de caractere.",
  "The next 30 days": "Următoarele 30 de zile",
  "The next step is elsewhere on this page. Show the step takes you to its control.": "Pasul următor se află în altă parte a acestei pagini. Arată pasul te duce la comanda lui.",
  "The offline map for this region is deleted. Your saved places and notes are kept.": "Harta offline a acestei regiuni a fost ștearsă. Locurile și notițele salvate sunt păstrate.",
  "The photo service is not ready. Check again in a moment.": "Serviciul foto nu este pregătit. Verifică din nou peste puțin timp.",
