  "Tap “Add to day list” on a place in Saved places.": "Atinge „Adaugă la lista zilei” la un loc din Locuri salvate.",
  "Tapping requests approximate location (~1 km) to find nearby places through our server. The map provider can see the viewed area and IP address when the map opens. We keep no location history.": "La atingere, se solicită locația aproximativă (~1 km) pentru a găsi locuri din apropiere prin serverul nostru. Furnizorul hărții poate vedea zona afișată și adresa IP când se deschide harta. Nu păstrăm istoricul locației.",
