  "Test notification sent.": "Notificare de test trimisă.",
  "Text to copy": "Text de copiat",
  "The alert could not be restored. Refresh the list to check its status.": "Alerta nu a putut fi restabilită. Actualizează lista pentru a-i verifica statutul.",
  "The application could not be submitted.": "Cererea nu a putut fi trimisă.",
  "The arrival time has also passed. Enter ticket times for an upcoming or ongoing trip.": "Și ora sosirii a trecut. Introdu orele de pe bilet pentru o călătorie viitoare sau în desfășurare.",
  "The automatic event provider is not enabled yet. Verified editorial listings are shown in the meantime.": "Furnizorul automat de evenimente nu este încă activat. Între timp, sunt afișate liste editoriale verificate.",
  "The change could not be saved. Your previous records are preserved; check storage and retry.": "Modificarea nu a putut fi salvată. Înregistrările anterioare sunt păstrate; verifică stocarea și încearcă din nou.",
  "The control for this step is not open on this screen.": "Comanda pentru acest pas nu este deschisă pe acest ecran.",
