  "The document could not be read. You can paste its text instead.": "Documentul nu a putut fi citit. Poți lipi textul în schimb.",
  "The end date cannot be before arrival.": "Data de încheiere nu poate fi înaintea sosirii.",
  "The end date cannot be before the start date.": "Data de încheiere nu poate fi înaintea datei de început.",
  "The estimate is partial because some activity or transport costs are missing. Flights are excluded.": "Estimarea este parțială deoarece lipsesc unele costuri de activități sau transport. Zborurile nu sunt incluse.",
  "The estimate keeps its days, travellers, source prices and exchange rate. It is not an expense.": "Estimarea păstrează zilele, călătorii, prețurile sursă și cursul valutar. Nu este o cheltuială.",
