  "The existing attachment in this trip will be replaced with your selection.": "Atașamentul existent al acestei călătorii va fi înlocuit cu selecția ta.",
  "The file must be smaller than 5 MB.": "Fișierul trebuie să fie mai mic de 5 MB.",
  "The idea behind your trip": "Ideea din spatele călătoriei tale",
