  "A city route you can adapt with separate days for the Seine, the museum district and Montmartre.": "Un traseu urban pe care îl poți adapta, cu zile separate pentru Sena, zona muzeelor și Montmartre.",
  "A classic but rewarding choice for travellers who want art, history and food in an energetic city itinerary.": "O alegere clasică, dar plină de satisfacții, pentru călătorii care vor artă, istorie și gastronomie într-un itinerar urban plin de energie.",
  "A flexible route combining Tirana with the beaches around Ksamil.": "Un traseu flexibil care combină Tirana cu plajele din jurul Ksamilului.",
  "A good balance of history, nature and familiar food make this an affordable Balkan route.": "Un echilibru bun între istorie, natură și mâncare familiară face din acest traseu balcanic o opțiune accesibilă.",
  "A major trip combining tradition, technology and food.": "O călătorie amplă care îmbină tradiția, tehnologia și gastronomia.",
  "A route starting around Göreme that you can adapt to your pace across valleys and nearby towns.": "Un traseu care începe în zona Göreme și pe care îl poți adapta ritmului tău, prin văi și localitățile apropiate.",
  "A short flight, walkable centre and modern city experience.": "Un zbor scurt, un centru ușor de explorat pe jos și o experiență urbană modernă.",
  "A starting plan to adapt around Midtown, Central Park and the Brooklyn Bridge area.": "Un plan de pornire pe care îl poți adapta în jurul Midtown, Central Park și zonei Brooklyn Bridge.",
  "A starting route to shape around caldera views, island villages and time by the coast.": "Un traseu de pornire pe care îl poți modela în jurul priveliștilor spre calderă, satelor insulei și timpului petrecut pe coastă.",
  "A strong food culture and affordable local costs make it a balanced short break.": "O cultură gastronomică bogată și costuri locale accesibile fac din această destinație o alegere echilibrată pentru o escapadă scurtă.",
  "A varied long-haul choice for travellers seeking street food, culture and a city-and-island combination.": "O opțiune variată, la mare distanță, pentru călătorii care caută mâncare stradală, cultură și o combinație între oraș și insule.",
  "A walkable centre and coastal walks make this a comfortable first international trip.": "Un centru ușor de explorat pe jos și plimbările pe coastă fac din această destinație o primă călătorie în străinătate confortabilă.",
  "Adapt to your pace": "Adaptează la ritmul tău",
