  "Diplomatic mission": "Misiune diplomatică",
  "Do not photograph people or official buildings without permission.": "Nu fotografia persoane sau clădiri oficiale fără permisiune.",
  "Do not photograph people without permission; photography of military and certain official buildings is prohibited. Drinking or being under the influence in public is illegal. Licensing and other conditions vary by emirate.": "Nu fotografia persoane fără permisiune; fotografierea clădirilor militare și a anumitor clădiri oficiale este interzisă. Consumul de alcool sau starea de ebrietate în public sunt ilegale. Licențierea și alte condiții variază în funcție de emirat.",
  "Download flight and accommodation documents": "Descarcă documentele zborului și ale cazării",
  "Dress modestly in public and religious spaces.": "Îmbracă-te decent în spațiile publice și religioase.",
  "Dress modestly when visiting mosques, churches and monasteries.": "Îmbracă-te decent când vizitezi moschei, biserici și mănăstiri.",
