  "Easy": "Ușor",
  "Economy–mid-range": "Economic–mediu",
  "Eligible non-resident tourists can use participating stores. Minimum AED 250 excluding VAT per refund transaction; passport and purchase record are needed. Present goods for validation before departure. Check official deadlines, exclusions and deductions.": "Turiștii nerezidenți eligibili pot folosi magazinele participante. Minimum AED 250 fără TVA pentru fiecare operațiune de rambursare; sunt necesare pașaportul și dovada cumpărăturii. Prezintă bunurile pentru validare înainte de plecare. Verifică termenele, excluderile și deducerile oficiale.",
  "Eligible travellers resident outside Türkiye may use authorised Tax Free shops. Present goods and the printed e-invoice to customs on departure; confirm current eligibility, spending and export-deadline rules before buying.": "Călătorii eligibili cu reședința în afara Türkiye pot folosi magazinele Tax Free autorizate. Prezintă bunurile și factura electronică tipărită la vamă, la plecare; confirmă regulile actuale privind eligibilitatea, valoarea cumpărăturilor și termenul de export înainte să cumperi.",
  "Eligible visitors can use participating stores. Keep your passport, receipts and goods; confirm the current spending threshold. From 1 November 2026, refunds follow export confirmation by Customs. Parcels sent abroad by the buyer are excluded.": "Vizitatorii eligibili pot folosi magazinele participante. Păstrează pașaportul, bonurile și bunurile; confirmă pragul actual de cheltuieli. Din 1 noiembrie 2026, rambursarea are loc după confirmarea exportului de către vamă. Coletele trimise în străinătate de cumpărător sunt excluse.",
  "Eligible visitors resident outside the EU face a minimum EUR 50 purchase threshold. Check export procedures with your passport, invoice and goods; verify shop participation and export deadlines in the official guidance.": "Pentru vizitatorii eligibili cu reședința în afara UE se aplică un prag minim de cumpărături de EUR 50. Verifică procedurile de export având pașaportul, factura și bunurile; confirmă participarea magazinului și termenele de export în ghidul oficial.",
  "Eligible visitors resident outside the EU may qualify. Purchases must exceed EUR 100 including tax in the same shop on the same day. Present passport, goods and barcoded form for PABLO/customs validation before checking luggage. Export must be completed by the end of the third month after purchase; check product exclusions.": "Vizitatorii eligibili cu reședința în afara UE pot beneficia de rambursare. Cumpărăturile trebuie să depășească EUR 100, cu taxe incluse, în același magazin și în aceeași zi. Prezintă pașaportul, bunurile și formularul cu cod de bare pentru validarea PABLO/vamală înainte de predarea bagajului. Exportul trebuie finalizat până la sfârșitul celei de-a treia luni după cumpărare; verifică produsele excluse.",
