  "Energetic": "Energic",
  "England, Scotland and Wales have no general tourist VAT refund for goods carried in luggage. Direct overseas delivery by the shop differs. Northern Ireland has a separate scheme subject to eligibility and export rules; check passport, residence evidence and shop forms.": "Anglia, Scoția și Țara Galilor nu oferă o rambursare generală a TVA pentru bunurile transportate de turiști în bagaje. Livrarea directă în străinătate de către magazin are alte reguli. Irlanda de Nord are un sistem separat, supus condițiilor de eligibilitate și export; verifică pașaportul, dovada reședinței și formularele magazinului.",
  "English": "Engleză",
  "Entering or bathing in public fountains is prohibited in many cities, including Rome and Florence. Additional municipal rules may restrict sitting on monument steps. Check local signs.": "Intrarea sau scăldatul în fântânile publice sunt interzise în multe orașe, inclusiv Roma și Florența. Reguli municipale suplimentare pot limita șederea pe treptele monumentelor. Verifică indicatoarele locale.",
  "Entering or sitting on historic fountains and monuments may lead to fines.": "Intrarea în fântâni istorice sau șederea pe acestea și pe monumente pot duce la amenzi.",
  "Entry with Turkish ID card": "Intrare cu carte de identitate turcească",
  "Explore the centre on foot and take an early bus to make the most of a Mostar day trip.": "Explorează centrul pe jos și ia un autobuz devreme pentru a profita de excursia de o zi la Mostar.",
  "Exploring": "Explorare",
  "F": "F",
  "FCDO recommends carrying your passport and keeping a copy separately in a safe place. Photographing military or police premises, personnel or vehicles can cause difficulties with authorities; follow security notices and officials’ instructions.": "FCDO recomandă să porți pașaportul și să păstrezi separat o copie, într-un loc sigur. Fotografierea clădirilor, personalului sau vehiculelor militare ori de poliție poate provoca probleme cu autoritățile; respectă anunțurile de securitate și indicațiile oficialilor.",
  "First step": "Primul pas",
  "First-time international travellers and city explorers": "Cei aflați la prima călătorie în străinătate și exploratorii urbani",
  "Foggy": "Ceață",
