  "Food · Culture": "Gastronomie · Cultură",
  "Food, culture and affordable travel": "Gastronomie, cultură și călătorie accesibilă",
  "For consular services, check the jurisdiction of the consulates general in Vienna, Salzburg or Bregenz.": "Pentru servicii consulare, verifică jurisdicția consulatelor generale din Viena, Salzburg sau Bregenz.",
  "For travel within Türkiye, check your carrier's identity requirements. If arriving from abroad, confirm entry rules for your passport with the official source.": "Pentru călătorii în Türkiye, verifică cerințele de identificare ale transportatorului. Dacă sosești din străinătate, confirmă regulile de intrare pentru pașaportul tău la sursa oficială.",
