  "Gifts": "Cadouri",
  "GoTürkiye says tips are not expected at esnaf lokantası restaurants, but are appreciated. This does not establish a fixed percentage for every business; ask about its practice before paying.": "GoTürkiye precizează că bacșișul nu este așteptat la restaurantele de tip esnaf lokantası, dar este apreciat. Aceasta nu stabilește un procent fix pentru fiecare local; întreabă care este practica înainte de a plăti.",
