  "Lounge": "Salon de așteptare",
  "Lunch service is commonly around 13:00–16:00 and dinner starts from about 20:00. Some shops close between 14:00 and 17:00, and Sunday closures are common. These are general patterns; check the particular business and local holidays.": "Prânzul se servește de obicei între 13:00–16:00, iar cina începe în jurul orei 20:00. Unele magazine se închid între 14:00 și 17:00, iar duminica sunt frecvent închise. Acestea sunt obiceiuri generale; verifică localul respectiv și sărbătorile locale.",
  "March–May · October–November": "Martie–mai · Octombrie–noiembrie",
  "Markets": "Piețe",
  "May–June · September": "Mai–iunie · Septembrie",
  "Meal times can be later than you expect; check reservation hours.": "Orele de masă pot fi mai târzii decât te aștepți; verifică orele rezervărilor.",
  "Metro and public transport": "Metrou și transport public",
  "Mid-range–premium": "Mediu–premium",
  "Modern city experiences, shopping and structured transport suit travellers who prioritise comfort.": "Experiențele urbane moderne, cumpărăturile și transportul bine organizat se potrivesc călătorilor care pun confortul pe primul loc.",
  "Most shops close on public holidays and transit services may be reduced. Some museums open on Sundays but close on the following Monday. Confirm your daily plan against each venue’s calendar and the current transport timetable.": "Majoritatea magazinelor se închid de sărbătorile legale, iar serviciile de transport pot fi reduse. Unele muzee se deschid duminica, dar se închid lunea următoare. Verifică planul zilnic în raport cu calendarul fiecărei locații și orarul actual de transport.",
