  "PUB reports that tap water is suitable for drinking directly. This does not cover seawater, pools or outlets marked non-potable. Follow temporary local water notices.": "PUB precizează că apa de la robinet este potrivită pentru consum direct. Acest lucru nu se aplică apei de mare, piscinelor sau surselor marcate ca nepotabile. Respectă informările locale temporare privind apa.",
  "Pack a plug adapter": "Ia un adaptor de priză",
  "Pack medication and prescriptions": "Ia medicamentele și rețetele",
  "Pair the Old City with the waterfront boulevard; the evening lights reveal a different side of Baku.": "Combină orașul vechi cu bulevardul de pe malul apei; luminile serii dezvăluie o altă față a orașului Baku.",
  "Palace": "Palat",
