  "Photography and public alcohol use": "Fotografierea și consumul de alcool în public",
  "Plan Sunday shopping ahead": "Planifică din timp cumpărăturile de duminică",
  "Plan a route": "Planifică un traseu",
  "Plan for later meals": "Planifică mese la ore mai târzii",
  "Plan local transfers": "Planifică transferurile locale",
  "Police in towns and cities.": "Poliție în orașe și localități urbane.",
  "Premium": "Premium",
  "Public bins are scarce, so you may need to carry small waste with you.": "Coșurile de gunoi publice sunt rare, așa că s-ar putea să fie nevoie să porți cu tine deșeurile mici.",
  "Public drinking water is closely monitored. Building plumbing and temporary local notices can differ; do not drink from outlets marked non-potable.": "Apa potabilă din rețeaua publică este atent monitorizată. Instalațiile clădirilor și informările locale temporare pot varia; nu bea din surse marcate ca nepotabile.",
  "Public tap water in Austria is generally suitable for drinking, so you can refill your bottle. This does not cover lakes, streams or fountains marked non-potable; follow temporary local notices.": "Apa de la robinet din rețeaua publică a Austriei este în general potrivită pentru băut, așa că îți poți reumple sticla. Acest lucru nu se aplică lacurilor, pâraielor sau fântânilor marcate ca nepotabile; respectă informările locale temporare.",
  "Punctuality matters for appointments and reservations.": "Punctualitatea contează la întâlniri și rezervări.",
  "Queue etiquette matters; do not cut in line.": "Respectarea cozilor contează; nu te băga în față.",
  "Rainy": "Ploios",
  "Reduced services on public holidays": "Servicii reduse de sărbătorile legale",
  "Refill from the tap": "Reumple de la robinet",
  "Respect local law and public-behaviour rules.": "Respectă legislația locală și regulile de comportament în public.",
  "Respect private areas around homes and signs in protected areas when exploring outdoors. Fires are not allowed everywhere: national parks, reserves and temporary fire bans have their own rules. Take litter away and check current local restrictions.": "Respectă zonele private din jurul locuințelor și indicatoarele din ariile protejate când explorezi natura. Focul nu este permis peste tot: parcurile naționale, rezervațiile și interdicțiile temporare de foc au reguli proprii. Ia gunoiul cu tine și verifică restricțiile locale actuale.",
  "Responsible access to nature": "Acces responsabil în natură",
  "Restaurant": "Restaurant",
  "Retail shops generally close on Sundays and public holidays. Station, airport and other special outlets or regional rules can provide exceptions. Legally permitted hours are not a shop’s actual schedule; check the business before visiting.": "Magazinele se închid în general duminica și de sărbătorile legale. Magazinele din gări, aeroporturi și alte puncte speciale sau regulile regionale pot constitui excepții. Programul permis prin lege nu este programul efectiv al unui magazin; verifică înainte de vizită.",
  "Rime fog": "Ceață cu chiciură",
  "Riverfronts, lively streets and straightforward city transport.": "Maluri de râu, străzi animate și transport urban simplu.",
  "Road accident procedure": "Procedura în caz de accident rutier",
  "Rules on alcohol, medicines and public conduct vary by emirate.": "Regulile privind alcoolul, medicamentele și comportamentul în public variază în funcție de emirat.",
  "Santorini": "Santorini",
  "Sarajevo": "Sarajevo",
  "Sava and Danube riverfronts": "Malurile Savei și Dunării",
  "Saying “Bonjour” when entering a shop or café is basic courtesy.": "A spune „Bonjour” la intrarea într-un magazin sau într-o cafenea este o formă elementară de politețe.",
  "Schengen visa required": "Viză Schengen obligatorie",
  "Serbia": "Serbia",
  "Set up an eSIM or data plan": "Configurează un eSIM sau un plan de date",
  "Severe hail risk": "Risc mare de grindină severă",
  "Severe showers": "Averse foarte puternice",
