  "<h1>Your account has been deleted</h1><p>Your LetsGo2Travel account and associated private records have been deleted. Your community content has been removed or anonymised. This email confirms that your deletion request is complete.</p>": "<h1>Contul tău a fost șters</h1><p>Contul tău LetsGo2Travel și înregistrările private asociate au fost șterse. Conținutul tău din comunitate a fost eliminat sau anonimizat. Acest e-mail confirmă finalizarea cererii tale de ștergere.</p>",
