  "Arrive at the destination": "Ajungi la destinație",
  "Arrive, reach your accommodation and get your bearings. Keep the first day to a short walk and a meal.": "Ajungi, mergi la cazare și familiarizează-te cu zona. Rezervă prima zi pentru o plimbare scurtă și o masă.",
  "Ask the community": "Întreabă comunitatea",
  "At this hour, a central place with easy transport and recent reviews is a safer choice.": "La această oră, un loc central, cu transport ușor accesibil și recenzii recente, este o alegere mai sigură.",
  "Check current official travel advice.": "Verifică recomandările oficiale actuale de călătorie.",
  "Check current official travel information.": "Verifică informațiile oficiale actuale de călătorie.",
  "Check duration, adult and child counts, and child ages.": "Verifică durata, numărul adulților și al copiilor și vârstele copiilor.",
  "Check local connections": "Verifică legăturile locale",
