  "Check today's events": "Verifică evenimentele de azi",
  "Choose a central, well-lit evening route": "Alege un traseu central și bine iluminat pentru seară",
  "Choose a departure city, a valid destination and 1–14 days.": "Alege orașul de plecare, o destinație validă și o durată de 1–14 zile.",
  "Choose a museum, neighbourhood or local market matching your interests; check opening hours and group nearby stops.": "Alege un muzeu, un cartier sau o piață locală potrivită intereselor tale; verifică programul și grupează opririle apropiate.",
  "Choose a nearby coast or nature area; check transport and weather, and leave time to rest.": "Alege o zonă de coastă sau de natură din apropiere; verifică transportul și vremea și lasă timp pentru odihnă.",
  "Choose a quiet café, library or waterfront nearby instead of a packed itinerary.": "Alege o cafenea liniștită, o bibliotecă sau o promenadă din apropiere, în locul unui program aglomerat.",
  "Choose a sheltered option instead of exposed terrain.": "Alege un loc adăpostit în locul unui teren expus.",
  "Choose a valid passport country and type.": "Alege o țară emitentă și un tip de pașaport valide.",
  "Compare reservations for comfortable transfers and an optional guided experience.": "Compară rezervările pentru transferuri confortabile și o experiență opțională cu ghid.",
  "Compare well-rated local food nearby.": "Compară opțiunile de mâncare locală bine evaluate din apropiere.",
