  "Merge onto the road": "Intră pe drum",
  "Open a nearby gallery, historic building or exhibition that matches your interest.": "Descoperă o galerie, o clădire istorică sau o expoziție din apropiere, potrivită intereselor tale.",
  "Plan a short central walk and a local meal; leave time for the return journey.": "Planifică o plimbare scurtă prin centru și o masă locală; lasă timp pentru drumul de întoarcere.",
