  "Reconfirm the entry rule for your selected passport with an official source before booking.": "Confirmă din nou regulile de intrare pentru pașaportul ales dintr-o sursă oficială înainte de rezervare.",
  "Some interests had limited venue coverage; this plan uses the available results.": "Pentru unele interese au fost disponibile puține locuri; planul folosește rezultatele disponibile.",
  "Stops ordered for your travel preferences. Visit times are suggestions; travel times are calculated on the map.": "Opririle sunt ordonate după preferințele tale. Duratele vizitelor sunt sugestii; timpii de deplasare se calculează pe hartă.",
